#!/usr/bin/env python3
"""Offline integration verifier for all four independent workstreams."""
from __future__ import annotations
import csv
import json
import shutil
import subprocess
import sys
import tempfile
from pathlib import Path

ROOT = Path(__file__).resolve().parent
STREAMS = ("packing", "schedule", "routing", "quality")
ARTIFACTS = {
    "packing": ("input.json", "solve.py", "result.json", "report.md"),
    "schedule": ("input.json", "solve.py", "result.json", "report.md"),
    "routing": ("input.json", "solve.py", "result.json", "report.md"),
    "quality": ("input.json", "solve.py", "result.json", "cleaned.csv", "report.md"),
}


def check_stream_commands() -> None:
    for stream in STREAMS:
        proc = subprocess.run([sys.executable, "solve.py", "--check"], cwd=ROOT / stream, text=True, capture_output=True)
        if proc.returncode != 0:
            raise AssertionError(f"{stream} --check failed: {proc.stdout}{proc.stderr}")
        print(f"{stream} --check passed")


def independent_checks() -> None:
    packing = json.loads((ROOT / "packing/result.json").read_text())
    pin = json.loads((ROOT / "packing/input.json").read_text())
    assignment = packing["assignment"]
    if any(assignment[x] is None for x in pin["required"]):
        raise AssertionError("packing mandatory item omitted")
    loads = {box: 0 for box in pin["boxes"]}
    values = {box: 0 for box in pin["boxes"]}
    weights = {item["id"]: item["weight"] for item in pin["items"]}
    vals = {item["id"]: item["value"] for item in pin["items"]}
    for item_id, box in assignment.items():
        if box is not None:
            if box not in loads:
                raise AssertionError("packing unknown box")
            loads[box] += weights[item_id]
            values[box] += vals[item_id]
    for box, spec in pin["boxes"].items():
        if loads[box] > spec["capacity"] or packing["loads"][box]["weight"] != loads[box]:
            raise AssertionError("packing capacity/load mismatch")
    if packing["objective"]["total_value"] != sum(values.values()):
        raise AssertionError("packing objective mismatch")
    if packing["exhaustive_proof"]["choice_space_assignments"] != 3 ** len(pin["items"]):
        raise AssertionError("packing enumeration count mismatch")
    for a, b in pin["different_box_pairs"]:
        if assignment[a] is not None and assignment[a] == assignment[b]:
            raise AssertionError("packing separation violation")
    print("packing independent objective/feasibility passed")

    schedule = json.loads((ROOT / "schedule/result.json").read_text())
    sin = json.loads((ROOT / "schedule/input.json").read_text())
    for name, scenario in sin["scenarios"].items():
        item = schedule["scenarios"][name]
        jobs = item["schedule"]
        if set(jobs) != set(sin["jobs"]):
            raise AssertionError("schedule job set mismatch")
        for job, rec in jobs.items():
            if rec["end"] - rec["start"] != sin["jobs"][job] or rec["start"] < 0:
                raise AssertionError("schedule duration/start mismatch")
            if any(rec["bench"] == u["bench"] and rec["start"] < u["end"] and u["start"] < rec["end"] for u in scenario["unavailable"]):
                raise AssertionError("schedule availability violation")
        for a, b in sin["precedence"]:
            if jobs[a]["end"] > jobs[b]["start"]:
                raise AssertionError("schedule precedence violation")
        tech = sin["technician_jobs"]
        for a in tech:
            for b in tech:
                if a < b and jobs[a]["start"] < jobs[b]["end"] and jobs[b]["start"] < jobs[a]["end"]:
                    raise AssertionError("schedule technician overlap")
        for a in jobs:
            for b in jobs:
                if a < b and jobs[a]["bench"] == jobs[b]["bench"] and jobs[a]["start"] < jobs[b]["end"] and jobs[b]["start"] < jobs[a]["end"]:
                    raise AssertionError("schedule bench overlap")
        if item["makespan"] != max(j["end"] for j in jobs.values()):
            raise AssertionError("schedule makespan mismatch")
    print("schedule independent feasibility passed")

    routing = json.loads((ROOT / "routing/result.json").read_text())
    rin = json.loads((ROOT / "routing/input.json").read_text())
    edge_cost = {}
    for a, b, cost in rin["edges"]:
        edge_cost[frozenset((a, b))] = cost
    required = set(rin["required"])
    for scenario in routing["scenarios"]:
        walk = scenario["walk"]
        if walk[0] != rin["start"] or walk[-1] != rin["start"] or not required.issubset(walk):
            raise AssertionError("routing walk coverage/endpoints mismatch")
        total = 0
        removed_key = frozenset(scenario["removed_edge"]) if scenario["removed_edge"] else None
        for a, b in zip(walk, walk[1:]):
            key = frozenset((a, b))
            if key not in edge_cost or key == removed_key:
                raise AssertionError("routing walk uses invalid/removed edge")
            total += edge_cost[key]
        if total != scenario["cost"]:
            raise AssertionError("routing cost mismatch")
    print("routing independent physical-walk checks passed")

    q = json.loads((ROOT / "quality/result.json").read_text())
    with (ROOT / "quality/cleaned.csv").open(newline="") as f:
        rows = list(csv.DictReader(f))
    if len(rows) != q["cleaned_rows"] or len(rows) != 5:
        raise AssertionError("quality cleaned-row count mismatch")
    if list(rows[0]) != ["sensor", "time", "revision", "raw", "calibrated", "in_band"]:
        raise AssertionError("quality columns mismatch")
    print("quality independent retained-row checks passed")


def corruption_rejection() -> None:
    for stream in STREAMS:
        with tempfile.TemporaryDirectory(prefix=f"verify-{stream}-") as temp:
            dst = Path(temp) / stream
            shutil.copytree(ROOT / stream, dst)
            result_path = dst / "result.json"
            data = json.loads(result_path.read_text())
            if stream == "packing":
                data["objective"]["total_value"] += 1
            elif stream == "schedule":
                data["scenarios"]["baseline"]["makespan"] += 1
            elif stream == "routing":
                data["scenarios"][0]["cost"] += 1
            else:
                data["cleaned_rows"] += 1
            result_path.write_text(json.dumps(data), encoding="utf-8")
            proc = subprocess.run([sys.executable, "solve.py", "--check"], cwd=dst, text=True, capture_output=True)
            if proc.returncode == 0:
                raise AssertionError(f"{stream} validator accepted corruption")
        print(f"{stream} disposable corruption rejected")


def main() -> int:
    before = {str(ROOT / stream / name): (ROOT / stream / name).read_bytes() for stream, names in ARTIFACTS.items() for name in names}
    check_stream_commands()
    independent_checks()
    corruption_rejection()
    after = {path: Path(path).read_bytes() for path in before}
    if before != after:
        raise AssertionError("original stream artifacts changed")
    print("original stream artifacts preserved byte-for-byte")
    print("verify_all passed")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

