#!/usr/bin/env python3
"""Offline integration verifier for all four independent workstreams."""
from __future__ import annotations
import csv
import hashlib
import json
import shutil
import subprocess
import sys
import tempfile
from pathlib import Path

ROOT = Path(__file__).resolve().parent
STREAMS = ("packing", "schedule", "routing", "quality")
ARTIFACTS = {
    "packing": ("input.json", "solve.py", "result.json", "report.md"),
    "schedule": ("input.json", "solve.py", "result.json", "report.md"),
    "routing": ("input.json", "solve.py", "result.json", "report.md"),
    "quality": ("input.json", "solve.py", "result.json", "cleaned.csv", "report.md"),
}


def check_stream_commands() -> None:
    for stream in STREAMS:
        proc = subprocess.run([sys.executable, "solve.py", "--check"], cwd=ROOT / stream, text=True, capture_output=True)
        if proc.returncode != 0:
            raise AssertionError(f"{stream} --check failed: {proc.stdout}{proc.stderr}")
        print(f"{stream} --check passed")


def independent_checks() -> None:
    packing = json.loads((ROOT / "packing/result.json").read_text())
    pin = json.loads((ROOT / "packing/input.json").read_text())
    assignment = packing["assignment"]
    if any(assignment[x] is None for x in pin["required"]):
        raise AssertionError("packing mandatory item omitted")
    loads = {box: 0 for box in pin["boxes"]}
    values = {box: 0 for box in pin["boxes"]}
    weights = {item["id"]: item["weight"] for item in pin["items"]}
    vals = {item["id"]: item["value"] for item in pin["items"]}
    for item_id, box in assignment.items():
        if box is not None:
            if box not in loads:
                raise AssertionError("packing unknown box")
            loads[box] += weights[item_id]
            values[box] += vals[item_id]
    for box, spec in pin["boxes"].items():
        if loads[box] > spec["capacity"] or packing["loads"][box]["weight"] != loads[box]:
            raise AssertionError("packing capacity/load mismatch")
    if packing["objective"]["total_value"] != sum(values.values()):
        raise AssertionError("packing objective mismatch")
    if packing["exhaustive_proof"]["choice_space_assignments"] != 3 ** len(pin["items"]):
        raise AssertionError("packing enumeration count mismatch")
    for a, b in pin["different_box_pairs"]:
        if assignment[a] is not None and assignment[a] == assignment[b]:
            raise AssertionError("packing separation violation")
    print("packing independent objective/feasibility passed")

    schedule = json.loads((ROOT / "schedule/result.json").read_text())
    sin = json.loads((ROOT / "schedule/input.json").read_text())
    for name, scenario in sin["scenarios"].items():
        item = schedule["scenarios"][name]
        jobs = item["schedule"]
        if set(jobs) != set(sin["jobs"]):
            raise AssertionError("schedule job set mismatch")
        for job, rec in jobs.items():
            if rec["end"] - rec["start"] != sin["jobs"][job] or rec["start"] < 0:
                raise AssertionError("schedule duration/start mismatch")
            if any(rec["bench"] == u["bench"] and rec["start"] < u["end"] and u["start"] < rec["end"] for u in scenario["unavailable"]):
                raise AssertionError("schedule availability violation")
        for a, b in sin["precedence"]:
            if jobs[a]["end"] > jobs[b]["start"]:
                raise AssertionError("schedule precedence violation")
        tech = sin["technician_jobs"]
        for a in tech:
            for b in tech:
                if a < b and jobs[a]["start"] < jobs[b]["end"] and jobs[b]["start"] < jobs[a]["end"]:
                    raise AssertionError("schedule technician overlap")
        for a in jobs:
            for b in jobs:
                if a < b and jobs[a]["bench"] == jobs[b]["bench"] and jobs[a]["start"] < jobs[b]["end"] and jobs[b]["start"] < jobs[a]["end"]:
                    raise AssertionError("schedule bench overlap")
        if item["makespan"] != max(j["end"] for j in jobs.values()):
            raise AssertionError("schedule makespan mismatch")
    print("schedule independent feasibility passed")

    routing = json.loads((ROOT / "routing/result.json").read_text())
    rin = json.loads((ROOT / "routing/input.json").read_text())
    edge_cost = {}
    for a, b, cost in rin["edges"]:
        edge_cost[frozenset((a, b))] = cost
    required = set(rin["required"])
    for scenario in routing["scenarios"]:
        walk = scenario["walk"]
        if walk[0] != rin["start"] or walk[-1] != rin["start"] or not required.issubset(walk):
            raise AssertionError("routing walk coverage/endpoints mismatch")
        total = 0
        removed_key = frozenset(scenario["removed_edge"]) if scenario["removed_edge"] else None
        for a, b in zip(walk, walk[1:]):
            key = frozenset((a, b))
            if key not in edge_cost or key == removed_key:
                raise AssertionError("routing walk uses invalid/removed edge")
            total += edge_cost[key]
        if total != scenario["cost"]:
            raise AssertionError("routing cost mismatch")
    print("routing independent physical-walk checks passed")

    q = json.loads((ROOT / "quality/result.json").read_text())
    with (ROOT / "quality/cleaned.csv").open(newline="") as f:
        rows = list(csv.DictReader(f))
    if len(rows) != q["cleaned_rows"] or len(rows) != 5:
        raise AssertionError("quality cleaned-row count mismatch")
    if list(rows[0]) != ["sensor", "time", "revision", "raw", "calibrated", "in_band"]:
        raise AssertionError("quality columns mismatch")
    print("quality independent retained-row checks passed")


def corruption_rejection() -> None:
    for stream in STREAMS:
        with tempfile.TemporaryDirectory(prefix=f"verify-{stream}-") as temp:
            dst = Path(temp) / stream
            shutil.copytree(ROOT / stream, dst)
            result_path = dst / "result.json"
            data = json.loads(result_path.read_text())
            if stream == "packing":
                data["objective"]["total_value"] += 1
            elif stream == "schedule":
                data["scenarios"]["baseline"]["makespan"] += 1
            elif stream == "routing":
                data["scenarios"][0]["cost"] += 1
            else:
                data["cleaned_rows"] += 1
            result_path.write_text(json.dumps(data), encoding="utf-8")
            proc = subprocess.run([sys.executable, "solve.py", "--check"], cwd=dst, text=True, capture_output=True)
            if proc.returncode == 0:
                raise AssertionError(f"{stream} validator accepted corruption")
        print(f"{stream} disposable corruption rejected")


def publishable_files(root: Path) -> set[str]:
    """Return the package boundary without consulting manifest.json."""
    paths = {"README.md", "dossier.md", "verify_all.py", "manifest.json"}
    for stream in STREAMS:
        base = root / stream
        for path in base.rglob("*"):
            if path.is_file() and not any(part.startswith(".atoma-") for part in path.relative_to(root).parts):
                paths.add(path.relative_to(root).as_posix())
    return paths


def integrity_error(message: str) -> AssertionError:
    return AssertionError(f"manifest integrity: {message}")


def validate_manifest(root: Path) -> None:
    expected = publishable_files(root) - {"manifest.json"}
    ordinary = {
        path.relative_to(root).as_posix()
        for path in root.rglob("*")
        if path.is_file() and not any(part.startswith(".atoma-") for part in path.relative_to(root).parts)
    }
    allowed = expected | {"manifest.json"}
    unexpected = sorted(ordinary - allowed)
    if unexpected:
        raise integrity_error(f"unexpected ordinary file: {unexpected[0]}")
    try:
        document = json.loads((root / "manifest.json").read_bytes())
    except (OSError, json.JSONDecodeError) as exc:
        raise integrity_error(f"manifest is not valid JSON: {exc}") from exc
    entries = document.get("files") if isinstance(document, dict) else None
    if not isinstance(entries, list):
        raise integrity_error("files must be a list")
    seen: set[str] = set()
    for entry in entries:
        if not isinstance(entry, dict) or set(entry) != {"path", "sha256"}:
            raise integrity_error("entry must contain only path and sha256")
        rel = entry["path"]
        digest = entry["sha256"]
        if not isinstance(rel, str) or not isinstance(digest, str):
            raise integrity_error("path and sha256 must be strings")
        if rel == "manifest.json":
            raise integrity_error("manifest.json must not list itself")
        if rel.startswith("/") or "\\" in rel or ".." in Path(rel).parts:
            raise integrity_error(f"escaping path: {rel}")
        if any(part.startswith(".atoma-") for part in Path(rel).parts):
            raise integrity_error(f"internal runtime path: {rel}")
        if rel in seen:
            raise integrity_error(f"duplicate entry: {rel}")
        seen.add(rel)
        candidate = root / rel
        try:
            candidate.relative_to(root)
        except ValueError as exc:
            raise integrity_error(f"escaping path: {rel}") from exc
        if not candidate.is_file():
            raise integrity_error(f"missing delivered file: {rel}")
        actual = hashlib.sha256(candidate.read_bytes()).hexdigest()
        if digest != actual:
            raise integrity_error(f"altered file/hash: {rel}")
    missing = sorted(expected - seen)
    if missing:
        raise integrity_error(f"omitted entry: {missing[0]}")
    if seen != expected:
        raise integrity_error("inventory does not match publication boundary")


def write_manifest(root: Path) -> None:
    files = [{"path": rel, "sha256": hashlib.sha256((root / rel).read_bytes()).hexdigest()}
             for rel in sorted(publishable_files(root) - {"manifest.json"})]
    (root / "manifest.json").write_text(json.dumps({"files": files}, indent=2) + "\n", encoding="utf-8")


def manifest_regressions() -> None:
    cases = ("internal", "missing", "altered", "omitted", "duplicate", "escaping", "unexpected")
    for case in cases:
        with tempfile.TemporaryDirectory(prefix=f"manifest-{case}-") as temp:
            dst = Path(temp)
            for rel in publishable_files(ROOT):
                target = dst / rel
                target.parent.mkdir(parents=True, exist_ok=True)
                shutil.copy2(ROOT / rel, target)
            doc = json.loads((dst / "manifest.json").read_text())
            if case == "internal":
                doc["files"].append({"path": ".atoma-probes.json", "sha256": "0" * 64})
            elif case == "missing":
                (dst / "README.md").unlink()
            elif case == "altered":
                doc["files"][0]["sha256"] = "0" * 64
            elif case == "omitted":
                doc["files"].pop()
            elif case == "duplicate":
                doc["files"].append(dict(doc["files"][0]))
            elif case == "escaping":
                doc["files"].append({"path": "../escape.txt", "sha256": "0" * 64})
            else:
                (dst / "unexpected.txt").write_text("not publishable", encoding="utf-8")
            if case != "missing":
                (dst / "manifest.json").write_text(json.dumps(doc), encoding="utf-8")
            try:
                validate_manifest(dst)
            except AssertionError as exc:
                if not str(exc).startswith("manifest integrity:"):
                    raise
            else:
                raise AssertionError(f"manifest regression accepted {case}")
        print(f"manifest {case} regression rejected")


def publication_copy_regression() -> None:
    with tempfile.TemporaryDirectory(prefix="publication-") as temp:
        dst = Path(temp)
        for rel in publishable_files(ROOT):
            target = dst / rel
            target.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(ROOT / rel, target)
        proc = subprocess.run([sys.executable, "verify_all.py", "--publication-check"], cwd=dst, text=True, capture_output=True)
        if proc.returncode != 0:
            raise AssertionError(f"clean publication copy failed: {proc.stdout}{proc.stderr}")
    print("clean publication-shaped copy passed")


def main() -> int:
    if "--write-manifest" in sys.argv:
        write_manifest(ROOT)
        return 0
    if "--publication-check" in sys.argv:
        validate_manifest(ROOT)
        check_stream_commands()
        independent_checks()
        print("publication verification passed")
        return 0
    before = {str(ROOT / stream / name): (ROOT / stream / name).read_bytes() for stream, names in ARTIFACTS.items() for name in names}
    before["dossier.md"] = (ROOT / "dossier.md").read_bytes()
    check_stream_commands()
    independent_checks()
    corruption_rejection()
    validate_manifest(ROOT)
    manifest_regressions()
    publication_copy_regression()
    after = {path: Path(path).read_bytes() for path in before}
    if before != after:
        raise AssertionError("original stream/dossier artifacts changed")
    print("original stream trees and dossier preserved byte-for-byte")
    print("verify_all passed")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
